 "content": """"Sum invoice amounts by customer."""
import csv
from decimal import Decimal, ROUND_HALF_UP

CENTS = Decimal("0.01")


def totals(path):
    """Exact per-customer sums, as Decimal. No rounding happens here."""
    result = {}
    with open(path, newline="") as source:
        for row in csv.DictReader(source):
            customer = row["customer"]
            amount = Decimal(row["amount"].strip())
            result[customer] = result.get(customer, Decimal(0)) + amount
    return result


def rounded_totals(path):
    """Per-customer sums rounded half up to cents, once, after summing."""
    return {
        customer: total.quantize(CENTS, rounding=ROUND_HALF_UP)
        for customer, total in totals(path).items()
    }


if __name__ == "__main__":
    for customer, amount in sorted(rounded_totals("invoices.csv").items()):
        print(f"{customer},{amount}")
