{
 "file_path": "/workspace/test_invoice_totals.py",
 "content": """"Regression tests for decimal-currency rounding in invoice_totals."""
import tempfile
import unittest
from decimal import Decimal, InvalidOperation
from pathlib import Path

from invoice_totals import rounded_totals, totals

REPO = Path(__file__).parent


class FixtureMixin:
    def write_csv(self, rows):
        """Write a temp CSV of (customer, amount) string pairs; return its path."""
        handle = tempfile.NamedTemporaryFile(
            mode="w", suffix=".csv", newline="", delete=False
        )
        self.addCleanup(Path(handle.name).unlink)
        with handle:
            handle.write("customer,amount\n")
            for customer, amount in rows:
                handle.write(f"{customer},{amount}\n")
        return handle.name


class TestRepoFixture(unittest.TestCase):
    """The checked-in invoices.csv is the original bug report."""

    def test_rounded_output(self):
        self.assertEqual(
            rounded_totals(REPO / "invoices.csv"),
            {"Aster": Decimal("0.30"), "Birch": Decimal("1.01")},
        )

    def test_two_decimal_places_in_output(self):
        for amount in rounded_totals(REPO / "invoices.csv").values():
            self.assertEqual(f"{amount}", f"{amount:.2f}")
            self.assertEqual(-amount.as_tuple().exponent, 2)


class TestHalfUp(FixtureMixin, unittest.TestCase):
    def test_exact_half_rounds_up_not_to_even(self):
        # Banker's rounding would give 1.00 here; the spec requires 1.01.
        path = self.write_csv([("Birch", "1.005")])
        self.assertEqual(rounded_totals(path)["Birch"], Decimal("1.01"))

    def test_half_up_when_even_digit_would_round_down(self):
        # 2.675 -> 2.68. Also the classic float trap: float("2.675") is
        # slightly below the tie, so a float pipeline yields 2.67.
        path = self.write_csv([("Cedar", "2.675")])
        self.assertEqual(rounded_totals(path)["Cedar"], Decimal("2.68"))

    def test_below_half_still_rounds_down(self):
        path = self.write_csv([("Cedar", "1.0049")])
        self.assertEqual(rounded_totals(path)["Cedar"], Decimal("1.00"))

    def test_negative_tie_rounds_away_from_zero(self):
        # ROUND_HALF_UP is "half away from zero", so a credit note of
        # -1.005 becomes -1.01, mirroring the positive case.
        path = self.write_csv([("Cedar", "-1.005")])
        self.assertEqual(rounded_totals(path)["Cedar"], Decimal("-1.01"))


class TestRoundAfterSumming(FixtureMixin, unittest.TestCase):
    def test_sum_then_round_differs_from_round_each_row(self):
        # Three half-cent rows sum to 0.015 -> 0.02. Rounding each row
        # first would give 0.01 * 3 = 0.03.
        path = self.write_csv([("Cedar", "0.005")] * 3)
        self.assertEqual(rounded_totals(path)["Cedar"], Decimal("0.02"))

    def test_intermediate_sums_are_never_rounded(self):
        path = self.write_csv([("Cedar", "0.004")] * 3)
        self.assertEqual(totals(path)["Cedar"], Decimal("0.012"))
        self.assertEqual(rounded_totals(path)["Cedar"], Decimal("0.01"))


class TestNoFloatResidue(FixtureMixin, unittest.TestCase):
    def test_tenths_sum_exactly(self):
        # 0.10 + 0.20 is 0.30000000000000004 in binary floating point.
        path = self.write_csv([("Aster", "0.10"), ("Aster", "0.20")])
        self.assertEqual(totals(path)["Aster"], Decimal("0.30"))

    def test_residue_does_not_accumulate_across_many_rows(self):
        # 100 rows of 0.10 is 9.99999999999998 as floats, which would
        # round down to 9.99 at the cent boundary in a float pipeline.
        path = self.write_csv([("Aster", "0.10")] * 100)
        self.assertEqual(totals(path)["Aster"], Decimal("10.0"))
        self.assertEqual(rounded_totals(path)["Aster"], Decimal("10.00"))

    def test_residue_never_crosses_a_rounding_boundary(self):
        # Sums to exactly 0.70; float accumulation lands just under it.
        rows = [("Aster", a) for a in ("0.10", "0.10", "0.10", "0.10", "0.10", "0.20")]
        path = self.write_csv(rows)
        self.assertEqual(rounded_totals(path)["Aster"], Decimal("0.70"))


class TestGrouping(FixtureMixin, unittest.TestCase):
    def test_groups_by_customer_independently(self):
        path = self.write_csv(
            [("Aster", "1.005"), ("Birch", "2.50"), ("Aster", "0.10")]
        )
        self.assertEqual(
            rounded_totals(path),
            {"Aster": Decimal("1.11"), "Birch": Decimal("2.50")},
        )

    def test_customer_names_are_not_normalised(self):
        path = self.write_csv([("Aster", "1.00"), ("aster", "2.00")])
        self.assertEqual(sorted(rounded_totals(path)), ["Aster", "aster"])

    def test_empty_file_has_no_totals(self):
        self.assertEqual(rounded_totals(self.write_csv([])), {})


class TestParsing(FixtureMixin, unittest.TestCase):
    def test_padded_amounts_are_accepted(self):
        # Decimal() rejects surrounding whitespace that float() tolerates.
        path = self.write_csv([("Cedar", "  1.005  ")])
        self.assertEqual(rounded_totals(path)["Cedar"], Decimal("1.01"))

    def test_malformed_amount_raises(self):
        # Deliberate: a bad invoice row surfaces rather than being skipped.
        path = self.write_csv([("Cedar", "not-a-number")])
        with self.assertRaises(InvalidOperation):
            totals(path)


if __name__ == "__main__":
    unittest.main(verbosity=2)
"
}

